// Generate `<map>.outline.json` sidecars for the county maps: simplified
// silhouettes of each map's road-network footprint, computed as a PARTITION of
// one shared grid so neighbouring counties tile along shared boundaries
// instead of overlapping. Every grid cell is owned by exactly one county (the
// one with the most road nodes in it; dilation to bridge rural road spacing
// claims only unowned cells, so it can never cross a boundary). Derived
// entirely from the committed map scrapes — no coordinates live in the repo
// (`web/public/*.json` is gitignored) — and regenerated by the predev/prebuild
// hooks.
//
//   node scripts/build-outlines.mjs [--debug]   (--debug prints the ASCII partition)

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { gunzipSync } from "node:zlib";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const debug = process.argv.includes("--debug");

const EARTH_R = 6371000.0;
const RAD = Math.PI / 180;
const CELL = 1000; // metres — boundaries are shared at this granularity

// The county-flagged entries of REAL_MAPS, read from the source of truth so a
// newly flagged county needs no change here.
const mapsTs = readFileSync(join(root, "src/lib/maps.ts"), "utf8");
const files = [...mapsTs.matchAll(/\w+:\s*\{\s*file:\s*"([^"]+)"[^}]*county:\s*true/g)].map((m) => m[1]);

const counties = [];
for (const file of files) {
  const gz = join(root, "public", `${file}.gz`);
  if (!existsSync(gz)) {
    console.warn(`outlines: missing ${file}.gz — skipped`);
    continue;
  }
  const doc = JSON.parse(gunzipSync(readFileSync(gz)).toString());
  counties.push({ file, origin: doc.meta.origin, nodes: doc.nodes });
}
if (counties.length === 0) process.exit(0);

// One shared frame (the first county's projection origin): county-local metres
// → GPS → shared metres, so every county rasterizes onto the same cells.
const shared = counties[0].origin;
const toShared = (x, y, origin) => {
  const lat = y / (EARTH_R * RAD) + origin[0];
  const lon = x / (EARTH_R * RAD * Math.cos(origin[0] * RAD)) + origin[1];
  return [(lon - shared[1]) * RAD * Math.cos(shared[0] * RAD) * EARTH_R, (lat - shared[0]) * RAD * EARTH_R];
};
const toLocal = (sx, sy, origin) => {
  const lat = sy / (EARTH_R * RAD) + shared[0];
  const lon = sx / (EARTH_R * RAD * Math.cos(shared[0] * RAD)) + shared[1];
  return [
    (lon - origin[1]) * RAD * Math.cos(origin[0] * RAD) * EARTH_R,
    (lat - origin[0]) * RAD * EARTH_R,
  ];
};

// Per-county node counts per shared cell.
let [x0, y0, x1, y1] = [Infinity, Infinity, -Infinity, -Infinity];
for (const c of counties) {
  c.pts = c.nodes.map((n) => toShared(n.x, n.y, c.origin));
  for (const [px, py] of c.pts) {
    x0 = Math.min(x0, px);
    y0 = Math.min(y0, py);
    x1 = Math.max(x1, px);
    y1 = Math.max(y1, py);
  }
}
const [w, h] = [Math.ceil((x1 - x0) / CELL) + 1, Math.ceil((y1 - y0) / CELL) + 1];
const idx = (x, y) => (y + 1) * (w + 2) + (x + 1); // padded 1 cell so contours close
const cells = (w + 2) * (h + 2);
const counts = counties.map(() => new Uint16Array(cells));
for (const [ci, c] of counties.entries()) {
  for (const [px, py] of c.pts) {
    counts[ci][idx(Math.floor((px - x0) / CELL), Math.floor((py - y0) / CELL))]++;
  }
}

// Ownership: the county with the most road nodes in the cell (its roads are
// clipped to the admin boundary, so along the county line density decides for
// the true owner). Ties break to list order — deterministic.
const owner = new Int8Array(cells).fill(-1);
for (let i = 0; i < cells; i++) {
  let [best, bestN] = [-1, 0];
  for (let ci = 0; ci < counties.length; ci++) {
    if (counts[ci][i] > bestN) {
      best = ci;
      bestN = counts[ci][i];
    }
  }
  owner[i] = best;
}

// Dilation to bridge rural road spacing — but only into UNOWNED cells (judged
// against the pre-dilation ownership), so a county can fatten into empty land
// yet never across a neighbour's boundary.
const dilated = Int8Array.from(owner);
for (let y = 0; y < h; y++) {
  for (let x = 0; x < w; x++) {
    if (owner[idx(x, y)] !== -1) continue;
    let [best, bestN] = [-1, 0];
    for (let ci = 0; ci < counties.length; ci++) {
      let n = 0;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          n += counts[ci][idx(x + dx, y + dy)];
        }
      }
      if (n > bestN) {
        best = ci;
        bestN = n;
      }
    }
    dilated[idx(x, y)] = best;
  }
}

if (debug) {
  const letters = "abcdefghijklmnop";
  let art = `\npartition (${w}×${h}, ${CELL} m cells): ` +
    counties.map((c, i) => `${letters[i]}=${c.file}`).join(" ") + "\n";
  for (let y = h - 1; y >= 0; y -= 3) {
    let line = "";
    for (let x = 0; x < w; x += 2) {
      const o = dilated[idx(x, y)];
      line += o === -1 ? "·" : letters[o];
    }
    art += line + "\n";
  }
  console.log(art);
}

// Marching squares over one county's owned cells → boundary loops → longest →
// Douglas-Peucker. Both sides of a shared boundary trace the identical cell
// edges, so the tiling survives up to the simplification tolerance (and the
// runtime mask chain absorbs that remainder).
function trace(ci) {
  const at = (x, y) => (dilated[idx(x, y)] === ci ? 1 : 0);
  const segs = [];
  for (let y = -1; y < h; y++) {
    for (let x = -1; x < w; x++) {
      const c = (at(x, y) << 0) | (at(x + 1, y) << 1) | (at(x + 1, y + 1) << 2) | (at(x, y + 1) << 3);
      const S = [x + 0.5, y];
      const E = [x + 1, y + 0.5];
      const N = [x + 0.5, y + 1];
      const W = [x, y + 0.5];
      const table = {
        1: [[W, S]], 2: [[S, E]], 3: [[W, E]], 4: [[E, N]], 5: [[W, N], [S, E]],
        6: [[S, N]], 7: [[W, N]], 8: [[N, W]], 9: [[N, S]], 10: [[N, E], [S, W]],
        11: [[N, E]], 12: [[E, W]], 13: [[E, S]], 14: [[S, W]],
      };
      for (const [a, b] of table[c] ?? []) segs.push([a, b]);
    }
  }
  const keyOf = (p) => `${p[0]},${p[1]}`;
  const from = new Map();
  for (const [a, b] of segs) from.set(keyOf(a), [a, b]);
  const seen = new Set();
  let best = [];
  for (const [k, [a]] of from) {
    if (seen.has(k)) continue;
    const loop = [];
    let cur = a;
    while (cur && !seen.has(keyOf(cur))) {
      seen.add(keyOf(cur));
      loop.push(cur);
      cur = from.get(keyOf(cur))?.[1];
    }
    if (loop.length > best.length) best = loop;
  }
  return best;
}

const simplify = (line, tol) => {
  if (line.length < 3) return line;
  const keep = new Uint8Array(line.length);
  keep[0] = keep[line.length - 1] = 1;
  const stack = [[0, line.length - 1]];
  while (stack.length) {
    const [i, j] = stack.pop();
    const [ax, ay] = line[i];
    const [bx, by] = line[j];
    const [dx, dy] = [bx - ax, by - ay];
    const len = Math.hypot(dx, dy) || 1;
    let far = -1;
    let fd = tol;
    for (let k = i + 1; k < j; k++) {
      const d = Math.abs((line[k][0] - ax) * dy - (line[k][1] - ay) * dx) / len;
      if (d > fd) {
        fd = d;
        far = k;
      }
    }
    if (far > 0) {
      keep[far] = 1;
      stack.push([i, far], [far, j]);
    }
  }
  return line.filter((_, i) => keep[i]);
};

for (const [ci, c] of counties.entries()) {
  const raw = trace(ci);
  const points = simplify(raw, 0.5).map(([gx, gy]) => {
    const [lx, ly] = toLocal(x0 + gx * CELL, y0 + gy * CELL, c.origin);
    return [Math.round(lx), Math.round(ly)];
  });
  const out = { origin: c.origin, points };
  const path = join(root, "public", `${c.file.replace(/\.json$/, "")}.outline.json`);
  writeFileSync(path, JSON.stringify(out));
  console.log(`outlines: ${c.file} → ${points.length} points (${raw.length} raw), ${JSON.stringify(out).length} bytes`);
}
